-- DE TAI 19 - BUOC 5: DDL POSTGRESQL 18, TEN TIENG VIET, LOI LOGIC BCNF.
-- Chay tren database dau_gia_19_bcnf sau 00_tao_database.sql.
-- Khong DROP, khong dung CREATE TABLE IF NOT EXISTS de che luoc do sai.
-- Neu schema dau_gia da ton tai, ca transaction dung lai, khong ghi de.
-- BCNF can chung minh bang phu thuoc ham: docs/BUOC_05_DDL_BCNF.md.

BEGIN;

CREATE SCHEMA dau_gia;

-- 1. NGUOI DUNG: MaNguoiDung va DiaChiThuDienTu la hai khoa ung vien.
CREATE TABLE dau_gia."NguoiDung" (
    "MaNguoiDung" bigint GENERATED BY DEFAULT AS IDENTITY,
    "HoTen" text NOT NULL,
    "DiaChiThuDienTu" text NOT NULL,
    "ThoiDiemTao" timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT nguoi_dung_kc PRIMARY KEY ("MaNguoiDung"),
    CONSTRAINT nguoi_dung_thu_dn UNIQUE ("DiaChiThuDienTu"),
    CONSTRAINT nguoi_dung_ten_hop_le CHECK (btrim("HoTen") <> ''),
    CONSTRAINT nguoi_dung_thu_hop_le CHECK (
        "DiaChiThuDienTu" = lower("DiaChiThuDienTu")
        AND "DiaChiThuDienTu" = btrim("DiaChiThuDienTu")
        AND position('@' IN "DiaChiThuDienTu") > 1
    )
);

-- 2. DANH MUC: ten chi duy nhat trong cung cha, khong duy nhat toan cuc.
CREATE TABLE dau_gia."DanhMuc" (
    "MaDanhMuc" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MaDanhMucCha" bigint,
    "TenDanhMuc" text NOT NULL,
    CONSTRAINT danh_muc_kc PRIMARY KEY ("MaDanhMuc"),
    CONSTRAINT danh_muc_cha_kn FOREIGN KEY ("MaDanhMucCha")
        REFERENCES dau_gia."DanhMuc" ("MaDanhMuc"),
    CONSTRAINT danh_muc_cung_cha_dn UNIQUE NULLS NOT DISTINCT
        ("MaDanhMucCha", "TenDanhMuc"),
    CONSTRAINT danh_muc_ten_hop_le CHECK (btrim("TenDanhMuc") <> ''),
    CONSTRAINT danh_muc_khong_tu_lam_cha CHECK (
        "MaDanhMucCha" IS DISTINCT FROM "MaDanhMuc"
    )
);

-- 3. TAI SAN: khong sao chep HoTen, email nguoi ban, TenDanhMuc vao day.
CREATE TABLE dau_gia."TaiSan" (
    "MaTaiSan" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MaNguoiBan" bigint NOT NULL,
    "MaDanhMuc" bigint NOT NULL,
    "LoaiTaiSan" text NOT NULL,
    "TenTaiSan" text NOT NULL,
    "MoTa" text NOT NULL DEFAULT '',
    "ThoiDiemTao" timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT tai_san_kc PRIMARY KEY ("MaTaiSan"),
    CONSTRAINT tai_san_nguoi_ban_kn FOREIGN KEY ("MaNguoiBan")
        REFERENCES dau_gia."NguoiDung" ("MaNguoiDung"),
    CONSTRAINT tai_san_danh_muc_kn FOREIGN KEY ("MaDanhMuc")
        REFERENCES dau_gia."DanhMuc" ("MaDanhMuc"),
    CONSTRAINT tai_san_loai_hop_le CHECK (
        "LoaiTaiSan" IN ('NgheThuat', 'SuuTam', 'DienTu')
    ),
    CONSTRAINT tai_san_ten_hop_le CHECK (btrim("TenTaiSan") <> '')
);

-- 4-6. BA LOP CON: giu cung dinh danh MaTaiSan, khong tao ma moi.
CREATE TABLE dau_gia."TacPhamNgheThuat" (
    "MaTaiSan" bigint,
    "TacGia" text NOT NULL,
    "ChatLieu" text NOT NULL,
    "NamSangTac" integer,
    CONSTRAINT nghe_thuat_kc PRIMARY KEY ("MaTaiSan"),
    CONSTRAINT nghe_thuat_cha_kn FOREIGN KEY ("MaTaiSan")
        REFERENCES dau_gia."TaiSan" ("MaTaiSan") ON DELETE CASCADE,
    CONSTRAINT nghe_thuat_tac_gia_hop_le CHECK (btrim("TacGia") <> ''),
    CONSTRAINT nghe_thuat_chat_lieu_hop_le CHECK (btrim("ChatLieu") <> ''),
    CONSTRAINT nghe_thuat_nam_hop_le CHECK ("NamSangTac" BETWEEN 1 AND 9999)
);

CREATE TABLE dau_gia."DoSuuTam" (
    "MaTaiSan" bigint,
    "NguonGoc" text NOT NULL,
    "DoHiem" text NOT NULL,
    "NamSanXuat" integer,
    CONSTRAINT suu_tam_kc PRIMARY KEY ("MaTaiSan"),
    CONSTRAINT suu_tam_cha_kn FOREIGN KEY ("MaTaiSan")
        REFERENCES dau_gia."TaiSan" ("MaTaiSan") ON DELETE CASCADE,
    CONSTRAINT suu_tam_nguon_goc_hop_le CHECK (btrim("NguonGoc") <> ''),
    CONSTRAINT suu_tam_do_hiem_hop_le CHECK (btrim("DoHiem") <> ''),
    CONSTRAINT suu_tam_nam_hop_le CHECK ("NamSanXuat" BETWEEN 1 AND 9999)
);

CREATE TABLE dau_gia."ThietBiDienTu" (
    "MaTaiSan" bigint,
    "ThuongHieu" text NOT NULL,
    "MauThietBi" text NOT NULL,
    "SoSeRi" text,
    "TinhTrang" text NOT NULL,
    CONSTRAINT dien_tu_kc PRIMARY KEY ("MaTaiSan"),
    CONSTRAINT dien_tu_cha_kn FOREIGN KEY ("MaTaiSan")
        REFERENCES dau_gia."TaiSan" ("MaTaiSan") ON DELETE CASCADE,
    CONSTRAINT dien_tu_so_se_ri_dn UNIQUE ("SoSeRi"),
    CONSTRAINT dien_tu_thuong_hieu_hop_le CHECK (btrim("ThuongHieu") <> ''),
    CONSTRAINT dien_tu_mau_hop_le CHECK (btrim("MauThietBi") <> ''),
    CONSTRAINT dien_tu_tinh_trang_hop_le CHECK (btrim("TinhTrang") <> ''),
    CONSTRAINT dien_tu_so_se_ri_hop_le CHECK ("SoSeRi" IS NULL OR btrim("SoSeRi") <> '')
);

-- 7. PHIEN DAU GIA: mot TaiSan co the tham gia NHIEU phien (nhung toi da mot phien DangMo).
-- GiaHienTai, MaLuotDanDau la du lieu suy dien: xem VIEW cuoi tep.
CREATE TABLE dau_gia."PhienDauGia" (
    "MaPhien" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MaTaiSan" bigint NOT NULL,
    "GiaKhoiDiem" numeric(18,2) NOT NULL,
    "BuocGia" numeric(18,2) NOT NULL,
    "ThoiDiemMo" timestamptz NOT NULL,
    "ThoiDiemDong" timestamptz NOT NULL,
    "TrangThai" text NOT NULL DEFAULT 'DangMo',
    "PhienBan" bigint NOT NULL DEFAULT 0,
    CONSTRAINT phien_kc PRIMARY KEY ("MaPhien"),
    CONSTRAINT phien_tai_san_kn FOREIGN KEY ("MaTaiSan")
        REFERENCES dau_gia."TaiSan" ("MaTaiSan"),
    CONSTRAINT phien_gia_khoi_diem_hop_le CHECK (
        "GiaKhoiDiem" > 0 AND "GiaKhoiDiem" <> 'NaN'::numeric
    ),
    CONSTRAINT phien_buoc_gia_hop_le CHECK (
        "BuocGia" > 0 AND "BuocGia" <> 'NaN'::numeric
    ),
    CONSTRAINT phien_thoi_gian_hop_le CHECK ("ThoiDiemDong" > "ThoiDiemMo"),
    CONSTRAINT phien_trang_thai_hop_le CHECK ("TrangThai" IN ('DangMo', 'DaDong')),
    CONSTRAINT phien_ban_khong_am CHECK ("PhienBan" >= 0)
);

-- 8. DANG KY: khoa ghep nguoi dung - phien, khong tao ma dang ky gia.
CREATE TABLE dau_gia."DangKyThamGia" (
    "MaPhien" bigint,
    "MaNguoiDung" bigint,
    "TrangThai" text NOT NULL DEFAULT 'DaDuyet',
    "ThoiDiemDangKy" timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT dang_ky_kc PRIMARY KEY ("MaPhien", "MaNguoiDung"),
    CONSTRAINT dang_ky_phien_kn FOREIGN KEY ("MaPhien")
        REFERENCES dau_gia."PhienDauGia" ("MaPhien"),
    CONSTRAINT dang_ky_nguoi_kn FOREIGN KEY ("MaNguoiDung")
        REFERENCES dau_gia."NguoiDung" ("MaNguoiDung"),
    CONSTRAINT dang_ky_trang_thai_hop_le CHECK ("TrangThai" IN ('DaDuyet', 'DaThuHoi'))
);

-- 9. LUOT TRA GIA: lich su cac luot da chap nhan, 3 khoa ung vien.
CREATE TABLE dau_gia."LuotTraGia" (
    "MaLuotTraGia" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MaPhien" bigint NOT NULL,
    "MaNguoiTraGia" bigint NOT NULL,
    "SoTien" numeric(18,2) NOT NULL,
    "MaYeuCau" uuid NOT NULL,
    "ThoiDiemChapNhan" timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT luot_tra_kc PRIMARY KEY ("MaLuotTraGia"),
    CONSTRAINT luot_tra_yeu_cau_dn UNIQUE ("MaYeuCau"),
    CONSTRAINT luot_tra_phien_gia_dn UNIQUE ("MaPhien", "SoTien"),
    -- Cap nay la sieu khoa phu de FK cua ket qua giu dung phien.
    CONSTRAINT luot_tra_ma_phien_dn UNIQUE ("MaLuotTraGia", "MaPhien"),
    CONSTRAINT luot_tra_dang_ky_kn FOREIGN KEY ("MaPhien", "MaNguoiTraGia")
        REFERENCES dau_gia."DangKyThamGia" ("MaPhien", "MaNguoiDung"),
    CONSTRAINT luot_tra_so_tien_hop_le CHECK ("SoTien" > 0 AND "SoTien" <> 'NaN'::numeric)
);

-- 10. KET QUA: moi phien toi da mot dong, gia thang lay tu luot tra gia.
CREATE TABLE dau_gia."KetQuaDauGia" (
    "MaPhien" bigint,
    "MaLuotThang" bigint,
    "ThoiDiemChot" timestamptz NOT NULL DEFAULT clock_timestamp(),
    CONSTRAINT ket_qua_kc PRIMARY KEY ("MaPhien"),
    CONSTRAINT ket_qua_phien_kn FOREIGN KEY ("MaPhien")
        REFERENCES dau_gia."PhienDauGia" ("MaPhien"),
    CONSTRAINT ket_qua_luot_cung_phien_kn FOREIGN KEY ("MaLuotThang", "MaPhien")
        REFERENCES dau_gia."LuotTraGia" ("MaLuotTraGia", "MaPhien")
);

-- 11. NHAT KY: mot giao dich co the co nhieu su kien, MaGiaoDich khong la khoa.
CREATE TABLE dau_gia."NhatKyThayDoi" (
    "MaNhatKy" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MaPhien" bigint NOT NULL,
    "HanhDong" text NOT NULL,
    "MaNguoiThucHien" bigint,
    "ChiTiet" jsonb NOT NULL,
    "ThoiDiemGhi" timestamptz NOT NULL DEFAULT clock_timestamp(),
    -- pg_current_xact_id() thay cho txid_current() (nhom ham da loi thoi).
    "MaGiaoDich" bigint NOT NULL DEFAULT (pg_current_xact_id()::text)::bigint,
    CONSTRAINT nhat_ky_kc PRIMARY KEY ("MaNhatKy"),
    CONSTRAINT nhat_ky_phien_kn FOREIGN KEY ("MaPhien")
        REFERENCES dau_gia."PhienDauGia" ("MaPhien"),
    CONSTRAINT nhat_ky_nguoi_kn FOREIGN KEY ("MaNguoiThucHien")
        REFERENCES dau_gia."NguoiDung" ("MaNguoiDung"),
    CONSTRAINT nhat_ky_hanh_dong_hop_le CHECK ("HanhDong" IN ('ChapNhanTraGia', 'DongPhien'))
);

-- FK don le chua bao dam TOTAL + DISJOINT: kiem tra ca 3 bang con khi COMMIT.
CREATE FUNCTION dau_gia.kiem_tra_lop_con_tai_san() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, dau_gia AS $$
DECLARE
    cac_ma bigint[];
    ma bigint;
    loai text;
    so_nghe_thuat integer;
    so_suu_tam integer;
    so_dien_tu integer;
BEGIN
    cac_ma := ARRAY[NEW."MaTaiSan", OLD."MaTaiSan"];
    FOR ma IN SELECT DISTINCT unnest(cac_ma) LOOP
        SELECT "LoaiTaiSan" INTO loai FROM dau_gia."TaiSan"
        WHERE "MaTaiSan" = ma;
        IF NOT FOUND THEN CONTINUE; END IF;
        SELECT count(*) INTO so_nghe_thuat FROM dau_gia."TacPhamNgheThuat" WHERE "MaTaiSan" = ma;
        SELECT count(*) INTO so_suu_tam FROM dau_gia."DoSuuTam" WHERE "MaTaiSan" = ma;
        SELECT count(*) INTO so_dien_tu FROM dau_gia."ThietBiDienTu" WHERE "MaTaiSan" = ma;
        IF so_nghe_thuat + so_suu_tam + so_dien_tu <> 1
           OR (loai = 'NgheThuat' AND so_nghe_thuat <> 1)
           OR (loai = 'SuuTam' AND so_suu_tam <> 1)
           OR (loai = 'DienTu' AND so_dien_tu <> 1) THEN
            RAISE EXCEPTION 'TaiSan % phai thuoc dung mot lop con khop LoaiTaiSan', ma
                USING ERRCODE = '23514';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER tai_san_lop_con
AFTER INSERT OR UPDATE OR DELETE ON dau_gia."TaiSan"
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION dau_gia.kiem_tra_lop_con_tai_san();

CREATE CONSTRAINT TRIGGER nghe_thuat_lop_con
AFTER INSERT OR UPDATE OR DELETE ON dau_gia."TacPhamNgheThuat"
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION dau_gia.kiem_tra_lop_con_tai_san();

CREATE CONSTRAINT TRIGGER suu_tam_lop_con
AFTER INSERT OR UPDATE OR DELETE ON dau_gia."DoSuuTam"
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION dau_gia.kiem_tra_lop_con_tai_san();

CREATE CONSTRAINT TRIGGER dien_tu_lop_con
AFTER INSERT OR UPDATE OR DELETE ON dau_gia."ThietBiDienTu"
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
EXECUTE FUNCTION dau_gia.kiem_tra_lop_con_tai_san();

-- Chi muc FK va truy van: khong thay the rang buoc khoa hay transaction.
CREATE INDEX tai_san_nguoi_ban_idx ON dau_gia."TaiSan" ("MaNguoiBan");
CREATE INDEX tai_san_danh_muc_idx ON dau_gia."TaiSan" ("MaDanhMuc");
CREATE INDEX danh_muc_cha_idx ON dau_gia."DanhMuc" ("MaDanhMucCha");
CREATE INDEX phien_tai_san_idx ON dau_gia."PhienDauGia" ("MaTaiSan");
-- Rang buoc nghiep vu: mot tai san KHONG nam trong hai phien dang mo cung luc
-- (van duoc dau gia lai o phien sau khi phien truoc da dong).
CREATE UNIQUE INDEX phien_mot_phien_mo_moi_tai_san
    ON dau_gia."PhienDauGia" ("MaTaiSan") WHERE "TrangThai" = 'DangMo';
CREATE INDEX phien_sap_dong_idx ON dau_gia."PhienDauGia" ("ThoiDiemDong") WHERE "TrangThai" = 'DangMo';
CREATE INDEX dang_ky_nguoi_idx ON dau_gia."DangKyThamGia" ("MaNguoiDung");
CREATE INDEX luot_tra_dang_ky_idx ON dau_gia."LuotTraGia" ("MaPhien", "MaNguoiTraGia");
CREATE INDEX luot_tra_dan_dau_idx ON dau_gia."LuotTraGia" ("MaPhien", "SoTien" DESC, "MaLuotTraGia" DESC);
CREATE INDEX nhat_ky_phien_idx ON dau_gia."NhatKyThayDoi" ("MaPhien");

-- VIEW duoc tinh moi khi SELECT, khong phai MATERIALIZED VIEW/cache.
-- Khong co luot: GiaHienTai va MaLuotDanDau deu NULL, khong gia lam gia khoi diem.
CREATE VIEW dau_gia."ThongTinPhienDauGia" AS
SELECT p.*, l."SoTien" AS "GiaHienTai", l."MaLuotTraGia" AS "MaLuotDanDau"
FROM dau_gia."PhienDauGia" AS p
LEFT JOIN LATERAL (
    SELECT b."MaLuotTraGia", b."SoTien"
    FROM dau_gia."LuotTraGia" AS b
    WHERE b."MaPhien" = p."MaPhien"
    ORDER BY b."SoTien" DESC, b."MaLuotTraGia" DESC
    LIMIT 1
) AS l ON true;

COMMENT ON TABLE dau_gia."NguoiDung" IS 'BCNF theo cac khoa MaNguoiDung va DiaChiThuDienTu';
COMMENT ON TABLE dau_gia."TaiSan" IS 'BCNF: thong tin nguoi ban va danh muc chi duoc tham chieu bang khoa ngoai';
COMMENT ON TABLE dau_gia."PhienDauGia" IS 'Loi logic BCNF; thong tin gia dan dau suy dien tai ThongTinPhienDauGia';
COMMENT ON TABLE dau_gia."LuotTraGia" IS 'BCNF: khoa MaLuotTraGia, MaYeuCau, va cap MaPhien-SoTien';
COMMENT ON VIEW dau_gia."ThongTinPhienDauGia" IS 'Anh xa hai thuoc tinh suy dien trong EER, khong luu lap gia hien tai';

COMMIT;
